Read Imported Data, count column C references, and keep all rows whose reference occurs more than once.  
Sort those rows by Balance ascending then Invoiced Date ascending, parsing mixed date formats.  
Write the header and the sorted duplicate rows as plain values into Duplicates!A1:E5, converting date-like values to datetime.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

src_name = "Imported Data"
if src_name not in vals.sheetnames:
    src_name = "Import Data" if "Import Data" in vals.sheetnames else vals.sheetnames[0]
src = vals[src_name]

out_name = "Duplicates"
if out_name not in wb.sheetnames:
    ws = wb.create_sheet(out_name)
else:
    ws = wb[out_name]


def clean(v):
    if isinstance(v, str):
        return v.strip()
    return v


def parse_date(v):
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if v is None:
        return None

    s = str(v).strip()
    if not s:
        return None

    formats = (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%m/%d/%Y",
        "%d/%m/%Y %H:%M:%S",
        "%Y/%m/%d",
    )

    for fmt in formats:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass

    return None


def date_value(v):
    dt = parse_date(v)
    if dt is not None:
        return dt
    return clean(v)


def to_float(v):
    if isinstance(v, (int, float)):
        return float(v)
    if v is None:
        return float("inf")

    s = str(v).replace(",", "").strip()
    try:
        return float(s)
    except ValueError:
        return float("inf")


counts = {}
records = []

for r in range(2, src.max_row + 1):
    ref = src.cell(row=r, column=3).value
    if ref is None or str(ref).strip() == "":
        continue

    key = str(ref).strip()
    counts[key] = counts.get(key, 0) + 1
    row_vals = [src.cell(row=r, column=c).value for c in range(1, 6)]
    records.append((r, key, row_vals))

dups = [rec for rec in records if counts[rec[1]] > 1]


def sort_key(rec):
    _, _, row_vals = rec
    balance = to_float(row_vals[4])
    dt = parse_date(row_vals[3])
    if dt is None:
        dt = datetime.max
    return (balance, dt)


dups.sort(key=sort_key)

for c in range(1, 6):
    ws.cell(row=1, column=c).value = clean(src.cell(row=1, column=c).value)

for i, rec in enumerate(dups[:4], start=2):
    _, _, row_vals = rec
    for c in range(1, 6):
        v = row_vals[c - 1]
        if c == 4:
            v = date_value(v)
        else:
            v = clean(v)
        ws.cell(row=i, column=c).value = v

for i in range(2, 6):
    if i > len(dups[:4]) + 1:
        for c in range(1, 6):
            ws.cell(row=i, column=c).value = None

print("duplicate rows:", len(dups))
for r in range(1, 6):
    print([ws.cell(row=r, column=c).value for c in range(1, 6)])

wb.save(OUT)
